    if (!e || depth > CG_MAX_DEPTH) return false;
    switch (e->kind) {
    case EXPR_INT: case EXPR_FLOAT: case EXPR_BOOL: case EXPR_IDENT:
        return true;
    case EXPR_BINARY:
        return cg_view_pure_expr(cg, e->as.binary.left, view, index, allow_at, depth + 1) &&
