int64_t fr_str_builder_with_capacity(int64_t capacity) {
    if (capacity < 0 || (uint64_t)capacity > (uint64_t)SIZE_MAX - 1) return 0;
    int64_t handle = fr_str_builder();
    if (!handle || capacity == 0) return handle;
    str_builder_t *builder = (str_builder_t *)(intptr_t)handle;
    size_t allocation_size = (size_t)capacity + 1;
    char *data = str_alloc(allocation_size);
    if (!data) return 0;
    builder->data = data;
    builder->cap = allocation_size;
    return handle;
}

static int builder_reserve(str_builder_t *builder, size_t extra) {
    if (!builder || builder->len == SIZE_MAX || extra > SIZE_MAX - builder->len - 1) return 0;
    size_t needed = builder->len + extra + 1;
    if (needed <= builder->cap) return 1;
    size_t cap = builder->cap ? builder->cap : 64;
    while (cap < needed) {
        if (cap > SIZE_MAX / 2) { cap = needed; break; }
        cap *= 2;
    }
    char *data = str_alloc(cap);
    if (!data) return 0;
    if (builder->len) memcpy(data, builder->data, builder->len);
    builder->data = data;
    builder->cap = cap;
    return 1;
}

static int64_t builder_append_bytes(int64_t handle, const char *data, size_t len) {
    str_builder_t *builder = (str_builder_t *)(intptr_t)handle;
    if (!builder_reserve(builder, len)) return 0;
    if (len) memmove(builder->data + builder->len, data, len);
    builder->len += len;
    return handle;
}

int64_t fr_str_builder_append(int64_t handle, const char *s) {
    return builder_append_bytes(handle, s, s ? strlen(s) : 0);
}

int64_t fr_str_builder_append_view(int64_t handle, int64_t view_handle,
                                   int64_t start, int64_t len) {
    const str_view_t *view = (const str_view_t *)(intptr_t)view_handle;
    size_t offset, count;
    if (!fr_detail_str_view_range(view, start, len, &offset, &count)) return 0;
    return builder_append_bytes(handle, count ? view->data + offset : NULL, count);
}

int64_t fr_str_builder_char(int64_t handle, int64_t ch) {
    /* These APIs build NUL-terminated byte strings. Never introduce a hidden
     * suffix by appending NUL, or silently narrow an out-of-range byte. */
    if (ch <= 0 || ch > 255) return 0;
    char byte = (char)ch;
    return builder_append_bytes(handle, &byte, 1);
}

char *fr_str_builder_finish(int64_t handle) {
    const str_builder_t *builder = (const str_builder_t *)(intptr_t)handle;
    if (!builder) return NULL;
    char *snapshot = str_alloc(builder->len + 1);
    if (!snapshot) return NULL;
    if (builder->len) memcpy(snapshot, builder->data, builder->len);
    snapshot[builder->len] = '\0';
    return snapshot;
}

char *fr_str_builder_finish_take(int64_t handle) {
    str_builder_t *builder = (str_builder_t *)(intptr_t)handle;
    if (!builder) return NULL;
    char *result = builder->data;
    if (!result) {
        result = str_alloc(1);
        if (!result) return NULL;
        result[0] = '\0';
    } else {
        if (builder->len >= builder->cap) return NULL;
        result[builder->len] = '\0';
    }
    builder->data = NULL;
    builder->len = 0;
    builder->cap = 0;
    return result;
}
